#include <bits/stdc++.h>
using namespace std;

int multiply(int a, int b, int n) {
    return (int)(((long long)a * b) % n);
}

int inverse(int a, int n) {
    int m = n;
    int r1 = 1, r2 = 0, r3 = 0, r4 = 1;
    while (a > 0 && n > 0) {
        if (n >= a) {
            r3 -= r1 * (n / a);
            r4 -= r2 * (n / a);
            n %= a;
        } else {
            int tmpA = a;
            a = n;
            n = tmpA;
            int tmpR1 = r1;
            r1 = r3;
            r3 = tmpR1;
            int tmpR2 = r2;
            r2 = r4;
            r4 = tmpR2;
        }
    }
    if (a == 0) {
        return r3 >= 0 ? r3 % m : m + (r3 % m);
    } else {
        return r1 >= 0 ? r1 % m : m + (r1 % m);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int P = 998244353;
    int n, k, l;
    cin >> n >> k >> l;

    std::vector<int> factorials(2 * n + 2, 1);
    for (int i = 1; i <= 2 * n + 1; i++) {
        factorials[i] = multiply(factorials[i - 1], i, P);
    }

    std::vector<int> oddDoubleFactorials(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        oddDoubleFactorials[i] = multiply(oddDoubleFactorials[i - 1], 2 * i - 1, P);
    }

    std::vector<std::vector<int>> segmentMatrix(2 * n + 2, std::vector<int>(n + 1, 0));

    for (int r = 1; r <= 2 * n + 1; r++) {
        for (int segK = 1; segK <= n; segK++) {
            if (((r % 2) != (segK % 2)) && (r - 1 >= segK) && (2 * n + 1 - r >= segK)) {
                int numerator = multiply(factorials[r - 1], factorials[2 * n + 1 - r], P);
                numerator = multiply(numerator, oddDoubleFactorials[(r - segK - 1) / 2], P);
                numerator = multiply(numerator, oddDoubleFactorials[(2 * n + 1 - r - segK) / 2], P);

                int denominator = multiply(factorials[r - segK - 1], factorials[2 * n + 1 - r - segK], P);
                denominator = multiply(denominator, factorials[segK], P);

                int denom_inv = inverse(multiply(denominator, oddDoubleFactorials[n], P), P);
                segmentMatrix[r][segK] = multiply(numerator, denom_inv, P);
            }
        }
    }

    int totalCount = 0;
    for (int r = 1; r <= 2 * n + 1; r++) {
        for (int kk = k; kk <= n; kk++) {
            totalCount += segmentMatrix[r][kk];
            totalCount %= P;
        }
    }

    totalCount = multiply(totalCount, l, P);
    totalCount = multiply(totalCount, inverse(2 * n + 1, P), P);

    cout << totalCount << "\n";

    return 0;
}
